tags: [idisposable, dispose-pattern, inheritance]
code:
  language: csharp
  harness: statements
  source: |
    var reader = new ReportReader();
    reader.Dispose();
    Console.WriteLine($"Base open: {reader.BaseStream.CanRead}, report open: {reader.ReportStream.CanRead}");

    class StreamOwner : IDisposable
    {
        private bool _disposed;
        public MemoryStream BaseStream { get; } = new MemoryStream();

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }

        protected virtual void Dispose(bool disposing)
        {
            if (_disposed)
            {
                return;
            }
            if (disposing)
            {
                BaseStream.Dispose();
            }
            _disposed = true;
        }
    }

    class ReportReader : StreamOwner
    {
        private bool _disposed;
        public MemoryStream ReportStream { get; } = new MemoryStream();

        protected override void Dispose(bool disposing)
        {
            if (_disposed)
            {
                return;
            }
            if (disposing)
            {
                ReportStream.Dispose();
            }
            _disposed = true;
        }
    }
